    /** 主开关:主页视频背景。 */
    private static Object buildVideoBgSwitch(Context ctx, ClassLoader cl) {
        Class<?> switchPrefCls = loadClassSafely(
                "com.sec.android.app.sbrowser.common.settings.SwitchPreferenceCustom", cl);
        Object pref = newInstance(switchPrefCls, new Class[]{Context.class}, ctx);

        callMethod(pref, "setTitle", tt(T("主页视频背景", "Homepage video background"), "video-background"));
        callMethod(pref, "setKey", "sbplus_enable_video_bg");
        String path = videoBgPath();
        callMethod(pref, "setSummary",
                path.isEmpty() ? T("点击选择视频文件作为主页背景", "Tap to choose a video as homepage background") : (T("已设置视频背景", "Video background set")));
        callMethod(pref, "setChecked", isVideoBgEnabled());
        callMethod(pref, "setSelectable", true);
        try {
            callMethod(pref, "setDividerVisible", true);
        } catch (Throwable ignored) {}

        try {
            Class<?> listenerType = listenerParamType(pref.getClass(), "setOnPreferenceClickListener");
            Object onPreferenceClick = java.lang.reflect.Proxy.newProxyInstance(cl,
                    new Class[]{listenerType},
                    new java.lang.reflect.InvocationHandler() {
                        @Override
                        public Object invoke(Object proxy, java.lang.reflect.Method m, Object[] args) {
                            try {
                                if (m.getName().equals("onPreferenceClick")) {
                                    Object clicked = args[0];
                                    Object actObj = callMethod(clicked, "getContext");
                                    if (actObj instanceof android.app.Activity) {
                                        navigateToVideoBgPicker((android.app.Activity) actObj);
                                    }
                                    return Boolean.TRUE;
                                }
                            } catch (Throwable t) {
                                MainModule.logMsg("[SBPlus] video bg navigate error: " + t);
                            }
                            return Boolean.FALSE;
                        }
                    });
            callMethod(pref, "setOnPreferenceClickListener", onPreferenceClick);
        } catch (Throwable t) {
            MainModule.logMsg("[SBPlus] video bg click bind failed: " + t);
        }

        try {
            Class<?> listenerType = listenerParamType(pref.getClass(), "setOnPreferenceChangeListener");
            Object changeListener = java.lang.reflect.Proxy.newProxyInstance(cl,
                    new Class[]{listenerType},
                    new java.lang.reflect.InvocationHandler() {
                        @Override
                        public Object invoke(Object proxy, java.lang.reflect.Method m, Object[] args) {
                            try {
                                if (m.getName().equals("onPreferenceChange")) {
                                    Object newVal = args[1];
                                    boolean enabled = newVal instanceof Boolean && (Boolean) newVal;
                                    saveVideoBgEnabled(enabled);
                                    MainModule.logMsg("[SBPlus] video bg toggled: " + enabled);
                                    // 立即生效: 开关一变就挂/摘视频层, 不必重启浏览器。
                                    // 必须 post 到主线程下一帧 —— onPreferenceChange 回调里
                                    // 直接动视图树会和偏好页自身的布局打架。
                                    try {
                                        new android.os.Handler(android.os.Looper.getMainLooper())
                                                .postDelayed(new Runnable() {
                                                    @Override public void run() {
                                                        refreshHomeVideo();
                                                    }
                                                }, 100);
                                    } catch (Throwable ignored) {}
                                    return Boolean.TRUE;
                                }
                            } catch (Throwable t) {
                                MainModule.logMsg("[SBPlus] video bg listener error: " + t);
                            }
                            return Boolean.FALSE;
                        }
                    });
            callMethod(pref, "setOnPreferenceChangeListener", changeListener);
        } catch (Throwable t) {
            MainModule.logMsg("[SBPlus] video bg listener bind failed: " + t);
        }

        return pref;
    }

    /** 主页美化子页:视频背景 / 去搜索框文字 / 移动添加快捷方式按钮。 */
    // ================= 自定义主题色(替换莫奈) =================
    private static void hookThemeHook(ClassLoader cl) {
        try {
            // 全局文字改色: 设置页/主页文字按 slot
            findAndHookMethod("android.widget.TextView", cl,
                "setText", CharSequence.class, new XC_MethodHook() {
                    @Override protected void afterHookedMethod(MethodHookParam param) throws Throwable {
                        applyTextColor(param.thisObject);
                    }
                });
            // setTextColor 直接钩: 覆盖走 ColorStateList / 样式 的小字
            try {
                findAndHookMethod("android.widget.TextView", cl,
                    "setTextColor", int.class, new XC_MethodHook() {
                        @Override protected void afterHookedMethod(MethodHookParam param) throws Throwable {
                            try {
                                if (sInThemeText) return;
                                if (!(param.thisObject instanceof android.widget.TextView)) return;
                                android.widget.TextView tv = (android.widget.TextView) param.thisObject;
                                int c = themeTextColorFor(tv);
                                if (c == -1 || c == tv.getCurrentTextColor()) return;
                                sInThemeText = true;
                                try { tv.setTextColor(c); } finally { sInThemeText = false; }
                            } catch (Throwable ignored) {}
                        }
                    });
            } catch (Throwable ignored) {}
            // View 挂载兜底: 遍历时也套用主题色
            findAndHookMethod("android.view.View", cl,
                "onAttachedToWindow", new XC_MethodHook() {
                    @Override protected void afterHookedMethod(MethodHookParam param) throws Throwable {
                        if (param.thisObject instanceof android.widget.TextView) applyTextColor(param.thisObject);
                    }
                });
            // 绘制兜底: 设置页文字被三星重设成蓝/默认色时强制 correction
            try {
            try {
                findAndHookMethod("android.widget.TextView", cl,
                    "onDraw", android.graphics.Canvas.class, new XC_MethodHook() {
                        @Override protected void beforeHookedMethod(MethodHookParam param) throws Throwable {
                            try {
                                if (sInThemeText) return;
                                // 早退:主题未启用时,这个 hook 挂在每个 TextView 的每一帧绘制上,
                                // 必须第一时间返回,不做任何取文本/查资源名/走父链的动作。
                                if (!isThemeActive()) return;
                                Object o = param.thisObject;
                                if (!(o instanceof android.widget.TextView)) return;
                                android.widget.TextView tvd = (android.widget.TextView) o;
                                android.content.Context ctxd = sAppContext;
                                if (ctxd == null) return;
                                int curD;
                                try { curD = tvd.getCurrentTextColor(); } catch (Throwable e2) { return; }
                                // tabs_icon(底部工具栏页面数) 强制用 S_HOME_ICON 色
                                {
                                    String tname = resEntryName(tvd);
                                    if ("tabs_icon".equals(tname)) {
                                        android.content.Context tctx = sAppContext;
                                        int icol = (tctx != null) ? ThemeColorHelper.getSlot(tctx, ThemeColorHelper.S_HOME_ICON) : -1;
                                        if (icol != -1 && curD != icol) {
                                            sInThemeText = true;
                                            try { tvd.setTextColor(icol); } finally { sInThemeText = false; }
                                        }
                                        // 页面图标: tabs_icon 的 background(标签图形) 染 S_HOME_ICON 色(与数字统一)
                                        // 幂等检查: 已是目标色不再重复 set(避免每帧触发 Drawable invalidate 重绘风暴);
                                        // 主题停用(icol==-1)时清除残留 colorFilter 恢复原色。
                                        if (icol != -1) {
                                            android.graphics.drawable.Drawable tbg = tvd.getBackground();
                                            if (tbg != null) {
                                                android.graphics.ColorFilter tcf = null;
                                                try { tcf = tbg.getColorFilter(); } catch (Throwable ignoredCF) {}
                                                boolean already = (tcf instanceof android.graphics.PorterDuffColorFilter)
                                                        && reflectColorFilterColor(tcf) == icol;
                                                if (!already) {
                                                    tbg.setColorFilter(icol, android.graphics.PorterDuff.Mode.SRC_IN);
                                                }
                                            }
                                        } else {
                                            try {
                                                android.graphics.drawable.Drawable tbg2 = tvd.getBackground();
                                                if (tbg2 != null && tbg2.getColorFilter() != null) tbg2.clearColorFilter();
                                            } catch (Throwable ignoredClean) {}
                                        }
                                        return;
                                    }
                                }
                                boolean inS = isInSettingsScreen(tvd);
                                if (!inS) return;
                                int targetD = themeTextColorFor(tvd);
                                if (targetD == -1) return;
                                // 仅在颜色确实不同才设色, 避免每次 onDraw 都 invalidate 造成重绘风暴
                                int curCol = tvd.getCurrentTextColor();
                                if (curCol == targetD) return;
                                sInThemeText = true;
                                try {
                                    tvd.setTextColor(targetD);
                                    try { tvd.setLinkTextColor(targetD); } catch (Throwable ignoredL) {}
                                    try { tvd.getPaint().setColor(targetD); } catch (Throwable ignoredP) {}
                                } finally { sInThemeText = false; }
                            } catch (Throwable ignored) {}
                        }
                    });
            } catch (Throwable ignored2) {}

            } catch (Throwable ignored2) {}
            // getTextColors: 三星值文字用 ColorStateList 渲染, 直接覆盖其解析
            try {
                findAndHookMethod("android.widget.TextView", cl,
                    "getTextColors", new XC_MethodHook() {
                        @Override protected void afterHookedMethod(MethodHookParam param) throws Throwable {
                            try {
                                if (sInThemeText) return;
                                Object o = param.thisObject;
                                if (!(o instanceof android.widget.TextView)) return;
                                android.widget.TextView tvv = (android.widget.TextView) o;
                                android.content.Context ctx = sAppContext;
                                if (ctx == null || !isThemeActive()) return;
                                if (!isInSettingsScreen(tvv)) return;
                                int t = themeTextColorFor(tvv);
                                if (t == -1) return;
                                // 走缓存:本钩子在每次 TextView 绘制时触发,
                                // 原实现每次都新建 ColorStateList + 两个数组。
                                param.setResult(cslFor(t));
                            } catch (Throwable ignored) {}
                        }
                    });
            } catch (Throwable ignored2b) {}
            // 主页图标(S_HOME_ICON): 给浏览器 UI 图标(含三星 Toolbar/AppCompat 家族)染主题色
            // 标准 ImageView + AppCompat 家族 + 三星 Toolbar 自定义图标, 都 hook setImageDrawable/setImageResource
            String[][] iconHooks = {
                {"android.widget.ImageView", "setImageDrawable", "drawable"},
                {"android.widget.ImageView", "setImageResource", "res"},
                {"androidx.appcompat.widget.AppCompatImageView", "setImageDrawable", "drawable"},
                {"androidx.appcompat.widget.AppCompatImageButton", "setImageDrawable", "drawable"},
                {"androidx.appcompat.widget.AppCompatImageButton", "setImageResource", "res"},
            };
            for (String[] h : iconHooks) {
                try {
                    findAndHookMethod(h[0], cl,
                        h[1], (h[2].equals("res") ? int.class : (Class<?>) android.graphics.drawable.Drawable.class),
                        new XC_MethodHook() {
                            @Override protected void afterHookedMethod(MethodHookParam param) throws Throwable {
                                tintHomeIcon(param.thisObject);
                            }
                        });
                } catch (Throwable ignored) {}
            }
            // 三星 Toolbar 自定义图标类(重写 setImageDrawable 不调父类): 按类名 hook 其 setImageDrawable
            for (String tn : new String[]{
                "com.sec.android.app.sbrowser.common.widget.ToolbarImageButton",
                "com.sec.android.app.sbrowser.common.widget.ToolbarImageView",
                "com.sec.android.app.sbrowser.toolbar.ToolbarImageButton",
                "com.sec.android.app.sbrowser.toolbar.ToolbarImageView"}) {
                try {
                    findAndHookMethod(tn, cl,
                        "setImageDrawable", android.graphics.drawable.Drawable.class,
                        new XC_MethodHook() {
                            @Override protected void afterHookedMethod(MethodHookParam param) throws Throwable {
                                tintHomeIcon(param.thisObject);
                            }
                        });
                } catch (Throwable ignored) {}
            }

            // onDraw 兜底: 任何浏览器 UI ImageView 重绘时都确保染主题色(覆盖动态菜单图标)
            //
            // 2026-10-04 修复(主人反馈"图标会有一瞬间变成原来的颜色然后染上色"):
            // 原先挂在 **afterHookedMethod**，即"先绘制、后染色" —— 每一帧的顺序是
            //   ① 三星按原色把图标画到画布上（用户此刻看到原色）
            //   ② 我们的 afterHook 才把 drawable 染成主题色
            // 于是**每一帧都会先闪一下原色**。改为 **beforeHookedMethod**：
            // 在绘制发生之前就把颜色设好，当帧画出来的就是主题色，闪烁消失。
            //
            // 安全性：before 阶段只做"设置 drawable 的 colorFilter / view 的 imageTintList"，
            // 这两者都是影响绘制结果的属性，在 onDraw 之前设置正是标准时机
            // （与 View 自己在 onDraw 里用 paint 设色同理），不会触发额外的重绘请求，
            // 也不改变 onDraw 的返回值语义（它是 void）。
            try {
                findAndHookMethod("android.widget.ImageView", cl, "onDraw",
                    android.graphics.Canvas.class,
                    new XC_MethodHook() {
                        @Override protected void beforeHookedMethod(MethodHookParam param) throws Throwable {
                            try {
                                Object o = param.thisObject;
                                if (o instanceof android.widget.ImageView) {
                                    ensureIconTint((android.widget.ImageView) o);
                                }
                            } catch (Throwable ignored) {}
                        }
                    });
            } catch (Throwable ignored) {}
            // 开关三色
            try {
                findAndHookMethod("androidx.appcompat.widget.SwitchCompat", cl,
                    "setChecked", boolean.class, new XC_MethodHook() {
                        @Override protected void afterHookedMethod(MethodHookParam param) throws Throwable {
                            applySwitchColor(param.thisObject);
                        }
                    });
            } catch (Throwable ignored) {}
            // 探测: 记录真实 WebViewClient 类名(三星 override onPageFinished 不调 super)
            try {
                findAndHookMethod("android.webkit.WebView", cl,
                    "setWebViewClient", android.webkit.WebViewClient.class,
                    new XC_MethodHook() {
                        @Override protected void afterHookedMethod(MethodHookParam param) throws Throwable {
                            try {
                                if (param.args.length>0 && param.args[0]!=null)
                                    MainModule.logMsg("[SBPlus] WebViewClient cls=" + param.args[0].getClass().getName());
                            } catch (Throwable ignored) {}
                        }
                    });
            } catch (Throwable ignored) {}
            // 网页文字/背景: CSS 注入 (S_WEB_TEXT / S_WEB_BG)
            try {
                findAndHookMethod(android.webkit.WebViewClient.class,
                    "onPageFinished", android.webkit.WebView.class, String.class,
                    new XC_MethodHook() {
                        @Override protected void afterHookedMethod(MethodHookParam param) throws Throwable {
                            try {
                                MainModule.logMsg("[SBPlus] onPageFinished fired url=" + (param.args.length>1?String.valueOf(param.args[1]):""));
                                // 页面加载完成:同步嗅探/油猴图标显隐(网页显示,主页隐藏)
                                if (param.args.length > 1 && param.args[1] instanceof String) {
                                    showToolbarIconsForWeb(String.valueOf(param.args[1]));
                                    // 调试页面(internet://urls 等)中文化注入
                                    injectDebugPageTranslation((android.webkit.WebView) param.args[0], String.valueOf(param.args[1]));
                                }
                                Object wv = param.args[0];
                                if (!isThemeActive()) return;
                                if (!(wv instanceof android.webkit.WebView)) return;
                                android.content.Context ctx = sAppContext;
                                if (ctx == null) return;
                                int wtext = ThemeColorHelper.getSlot(ctx, ThemeColorHelper.S_WEB_TEXT);
                                int wbg = ThemeColorHelper.getSlot(ctx, ThemeColorHelper.S_WEB_BG);
                                if (wtext == -1 && wbg == -1) return;
                                String css = buildWebThemeCss(wtext, wbg);
                                final android.webkit.WebView fwv = (android.webkit.WebView) wv;
                                try {
                                    fwv.evaluateJavascript("(function(){" +
                                        "var e=document.getElementById('sbplusTheme');" +
                                        "if(e){e.parentNode.removeChild(e);}" +
                                        "var s=document.createElement('style');s.id='sbplusTheme';" +
                                        "s.textContent='" + SbTextUtils.jsQuote(css) + "';" +
                                        "(document.head||document.documentElement).appendChild(s);" +
                                        "})();", null);
                                } catch (Throwable e2) {
                                    try { fwv.loadUrl("javascript:(function(){" +
                                        "var s=document.createElement('style');s.id='sbplusTheme';" +
                                        "s.textContent='" + SbTextUtils.jsQuote(css) + "';" +
                                        "(document.head||document.documentElement).appendChild(s);" +
                                        "})();"); } catch (Throwable ignored3) {}
                                }
                                MainModule.logMsg("[SBPlus] web theme injected text=#" + Integer.toHexString(wtext)
                                    + " bg=#" + Integer.toHexString(wbg));
                            } catch (Throwable ignored) {}
                        }
                    });
            } catch (Throwable ignoredW) {}
            MainModule.logMsg("[SBPlus] theme hook registered");
            try {
                android.content.Context dctx = sAppContext;
                if (dctx != null) {
                    MainModule.logMsg("[SBPlus] SLOTS master=" + isThemeMasterEnabled() + " active=" + isThemeActive());
                    for (int si = 0; si <= ThemeColorHelper.S_SWITCH_OFF; si++) {
                        int sv = ThemeColorHelper.getSlot(dctx, si);
                        MainModule.logMsg("[SBPlus] SLOT[" + si + "]=" + (si==ThemeColorHelper.S_HOME_ICON?"HOME_ICON":si==ThemeColorHelper.S_HOME_TEXT?"HOME_TEXT":si==ThemeColorHelper.S_SETTINGS_TITLE?"SETTINGS_TITLE":si==ThemeColorHelper.S_SETTINGS_DESC?"SETTINGS_DESC":si==ThemeColorHelper.S_SETTINGS_BG?"SETTINGS_BG":si==ThemeColorHelper.S_WEB_TEXT?"WEB_TEXT":si==ThemeColorHelper.S_WEB_BG?"WEB_BG":si==ThemeColorHelper.S_SWITCH_ON?"SWITCH_ON":si==ThemeColorHelper.S_SWITCH_THUMB?"SWITCH_THUMB":"SWITCH_OFF") + "=#" + Integer.toHexString(sv));
                    }
                }
            } catch (Throwable ignoredS) {}

            // Dialog.show hook: 弹窗出现时强制染色工具栏图标
            try {
                findAndHookMethod(android.app.Dialog.class, "show", new XC_MethodHook() {
                    @Override
                    protected void afterHookedMethod(MethodHookParam param) throws Throwable {
                        try {
                            android.app.Dialog dlg = (android.app.Dialog) param.thisObject;
                            android.view.Window w = dlg.getWindow();
                            if (w != null && w.getDecorView() != null) {
                                final android.view.View root = w.getDecorView().getRootView();
                                root.postDelayed(new Runnable() {
                                    @Override
                                    public void run() {
                                        forceApplyAllToolbarIcons(root);
                                    }
                                }, 300);
                            }
                        } catch (Throwable ignored) {}
                    }
                });
                MainModule.logMsg("[SBPlus] Dialog.show hooked for icon tinting");
            } catch (Throwable t) {
                MainModule.logMsg("[SBPlus] Dialog.show hook failed: " + t);
            }

            // PopupWindow hook: 弹窗出现时强制染色工具栏图标
            try {
                findAndHookMethod(android.widget.PopupWindow.class, "showAsDropDown",
                        android.view.View.class, int.class, int.class, new XC_MethodHook() {
                    @Override
                    protected void afterHookedMethod(MethodHookParam param) throws Throwable {
                        try {
                            android.widget.PopupWindow pw = (android.widget.PopupWindow) param.thisObject;
                            android.view.View cv = pw.getContentView();
                            if (cv != null) {
                                final android.view.View root = cv.getRootView();
                                root.postDelayed(new Runnable() {
                                    @Override
                                    public void run() {
                                        forceApplyAllToolbarIcons(root);
                                    }
                                }, 300);
                            }
                        } catch (Throwable ignored) {}
                    }
                });
                findAndHookMethod(android.widget.PopupWindow.class, "showAtLocation",
                        android.view.View.class, int.class, int.class, int.class, new XC_MethodHook() {
                    @Override
                    protected void afterHookedMethod(MethodHookParam param) throws Throwable {
                        try {
                            android.widget.PopupWindow pw = (android.widget.PopupWindow) param.thisObject;
                            android.view.View cv = pw.getContentView();
                            if (cv != null) {
                                final android.view.View root = cv.getRootView();
                                root.postDelayed(new Runnable() {
                                    @Override
                                    public void run() {
                                        forceApplyAllToolbarIcons(root);
                                    }
                                }, 300);
                            }
                        } catch (Throwable ignored) {}
                    }
                });
                MainModule.logMsg("[SBPlus] PopupWindow hooks registered for icon tinting");
            } catch (Throwable t) {
                MainModule.logMsg("[SBPlus] PopupWindow hook failed: " + t);
            }
        } catch (Throwable t) { MainModule.logMsg("[SBPlus] theme hook err: " + t); }
    }

        private static String buildWebThemeCss(int text, int bg) {
        StringBuilder sb = new StringBuilder();
        if (text != -1) {
            String t = String.format("%06X", text & 0xFFFFFF);
            sb.append("*{color:#").append(t).append("!important;}");
        }
        if (bg != -1) {
            String b = String.format("%06X", bg & 0xFFFFFF);
            // 统一背景: 清空各层元素背景, 露出 body 的统一主题背景色
            sb.append("*{background-color:transparent!important;}");
            sb.append("html,body{background-color:#").append(b).append("!important;}");
        }
        return sb.toString();
    }

    /** JS 单引号字符串转义(用于拼接 javascript: 注入,防止单引号/反斜杠破坏 JS 语法)。 */
private static boolean isThemeMasterEnabled() {
        try {
            android.content.Context ctx = sAppContext;
            if (ctx == null) return false;
            // 走 ThemeColorHelper 的缓存,避免每个 View 都同步读 SharedPreferences。
            return ThemeColorHelper.masterEnabled(ctx);
        } catch (Throwable t) { return false; }
    }

    private static boolean isThemeActive() {
        try {
            android.content.Context ctx = sAppContext;
            if (ctx == null) return false;
            // 缓存版:主开关 + 是否有任一 slot 被设置。原实现每次都轮询 10 个 slot
            // 各读一次 SharedPreferences,在着色热路径上开销显著。
            return ThemeColorHelper.masterEnabled(ctx) && ThemeColorHelper.anySlotSet(ctx);
        } catch (Throwable ignored) {}
        return false;
    }

    private static void applyTextColor(Object obj) {
        try {
            if (!(obj instanceof android.widget.TextView)) return;
            android.widget.TextView tv = (android.widget.TextView) obj;
            int c = themeTextColorFor(tv);
            if (c == -1 || c == tv.getCurrentTextColor()) return;
            tv.setTextColor(c);
        } catch (Throwable ignored) {}
    }

    /** 设置页: 标题(>=13sp)用标题色, 说明用说明色; 非设置页用主页文字色. 未设置返回 -1. */
    private static int themeTextColorFor(android.view.View v) {
        android.content.Context ctx = sAppContext;
        if (ctx == null) return -1;
        if (!isThemeActive()) return -1;
        boolean settings = isInSettingsScreen(v);
        if (v instanceof android.widget.TextView) {
            float sp;
            try {
                sp = ((android.widget.TextView) v).getTextSize()
                        / v.getResources().getDisplayMetrics().scaledDensity;
            } catch (Throwable e) { sp = 14f; }
            int out;
            // 特例: 底部工具栏"页面数"(tabs_icon)用 S_HOME_ICON 色(与工具栏图标统一)
            String vn = resEntryName(v);
            if ("tabs_icon".equals(vn)) {
                out = ThemeColorHelper.getSlot(ctx, ThemeColorHelper.S_HOME_ICON);
            } else if (settings) {
                out = sp >= 13f
                        ? ThemeColorHelper.getSlot(ctx, ThemeColorHelper.S_SETTINGS_TITLE)
                        : ThemeColorHelper.getSlot(ctx, ThemeColorHelper.S_SETTINGS_DESC);
            } else {
                out = ThemeColorHelper.getSlot(ctx, ThemeColorHelper.S_HOME_TEXT);
            }
            // 诊断日志:每个 TextView 都会走到这里(长列表滚动时每帧数十次),
            // 字符串拼接 + getText + logcat 写入是实测最大的卡顿/发热来源之一。
            // 默认关闭,只在需要排查着色问题时把 VERBOSE_THEME_LOG 打开重新编译。
            if (VERBOSE_THEME_LOG) {
                if (out != -1) {
                    String txt = "";
                    try { CharSequence t = ((android.widget.TextView) v).getText(); if (t!=null) txt = t.toString(); } catch (Throwable ignored) {}
                    int grav = -1;
                    try { grav = ((android.widget.TextView) v).getGravity(); } catch (Throwable ignored2) {}
                    String cls = v.getClass().getSimpleName();
                    int cur = 0;
                    try { cur = ((android.widget.TextView) v).getCurrentTextColor(); } catch (Throwable ignored2) {}
                    MainModule.logMsg("[SBPlus] themeText " + (settings?"SET":"HOME") + " " + sp + "sp grav=" + grav + " cls=" + cls + " cur=#" + Integer.toHexString(cur) + " '" + txt + "' -> #" + Integer.toHexString(out));
                } else if (settings) {
                    // 设置页有文字但未命中: 也打印, 便于排查蓝色小字
                    String txt = "";
                    try { CharSequence t = ((android.widget.TextView) v).getText(); if (t!=null) txt = t.toString(); } catch (Throwable ignored) {}
                    if (txt != null && txt.length() > 0) {
                        int cur = 0; float sp0=0;
                        try { cur = ((android.widget.TextView) v).getCurrentTextColor(); sp0 = ((android.widget.TextView) v).getTextSize()/((android.widget.TextView) v).getResources().getDisplayMetrics().scaledDensity; } catch (Throwable ignored2) {}
                        MainModule.logMsg("[SBPlus] themeText-MISS SET " + sp0 + "sp cur=#" + Integer.toHexString(cur) + " '" + txt + "'");
                    }
                } else {
                    // 非设置页: 定位蓝色小字
                    String txt = "";
                    try { CharSequence t = ((android.widget.TextView) v).getText(); if (t!=null) txt = t.toString(); } catch (Throwable ignored) {}
                    int cur = 0; float sp0=0;
                    try { cur = ((android.widget.TextView) v).getCurrentTextColor(); sp0 = ((android.widget.TextView) v).getTextSize()/((android.widget.TextView) v).getResources().getDisplayMetrics().scaledDensity; } catch (Throwable ignored2) {}
                    // 蓝色系文字(蓝明显强) 即打印
                    int r0=(cur>>16)&0xff, g0=(cur>>8)&0xff, b0=cur&0xff;
                    if (b0 > 90 && b0 > (r0+40) && b0 > (g0+40)) {
                        String act="";
                        try {
                            android.content.Context cw = v.getContext();
                            while (cw != null) {
                                if (cw instanceof android.app.Activity) { act = cw.getClass().getName(); break; }
                                if (cw instanceof android.content.ContextWrapper) cw = ((android.content.ContextWrapper) cw).getBaseContext();
                                else break;
                            }
                        } catch (Throwable ignored3) {}
                        MainModule.logMsg("[SBPlus] themeText-BLUE " + sp0 + "sp cur=#" + Integer.toHexString(cur) + " act=" + act + " class=" + v.getClass().getName() + " '" + txt + "'");
                    }
                }
            }
            return out;
        }
        return settings ? ThemeColorHelper.getSlot(ctx, ThemeColorHelper.S_SETTINGS_TITLE)
                        : ThemeColorHelper.getSlot(ctx, ThemeColorHelper.S_HOME_TEXT);
    }

    /**
     * ColorStateList 缓存(2026-09-17 新增)。
     *
     * <p>动机:主题着色要在 {@code TextView.getTextColors()} 的 after 钩子里
     * 改写返回值,而该钩子跑在**每次 TextView 绘制**上。原实现每次 new 一个
     * {@code ColorStateList} 并连带分配两个 int[] 数组——绘制路径上按帧产生垃圾,
     * 会持续给 GC 添压力。而实际用到的颜色值是有限的(来自主题槽位的少数几种)。
     *
     * <p>{@code ColorStateList} 是不可变对象,可安全共享同一实例给多个 View。
     * 这里按颜色值缓存,并设上限防止意外增长。
     *
     * <p>单状态列表用 {@code valueOf}(内部同样缓存),多状态列表自己建。
     */
    private static final java.util.concurrent.ConcurrentHashMap<String, android.content.res.ColorStateList> sCslCache
            = new java.util.concurrent.ConcurrentHashMap<String, android.content.res.ColorStateList>();
    private static final int CSL_CACHE_MAX = 128;

    /** 取单状态(恒定色)的 ColorStateList。 */
    private static android.content.res.ColorStateList cslFor(int color) {
        // 键必须带类型前缀:单色与双色共用一张表,若只用整数做键,
        // 复合键(色A*31^色B)可能与某个真实颜色值相撞,返回错误的状态列表。
        String key = "1:" + color;
        android.content.res.ColorStateList c = sCslCache.get(key);
        if (c != null) return c;
        c = new android.content.res.ColorStateList(new int[][]{ new int[]{} }, new int[]{ color });
        if (sCslCache.size() >= CSL_CACHE_MAX) sCslCache.clear();
        android.content.res.ColorStateList prev = sCslCache.putIfAbsent(key, c);
        return prev != null ? prev : c;
    }

    /** 取"选中/未选中"两态 ColorStateList(Switch 轨道着色用)。 */
    private static android.content.res.ColorStateList cslChecked(int checkedColor, int normalColor) {
        String key = "2:" + checkedColor + ":" + normalColor;
        android.content.res.ColorStateList c = sCslCache.get(key);
        if (c != null) return c;
        c = new android.content.res.ColorStateList(
                new int[][]{
                        new int[]{ android.R.attr.state_checked },
                        new int[]{}
                },
                new int[]{ checkedColor, normalColor });
        if (sCslCache.size() >= CSL_CACHE_MAX) sCslCache.clear();
        android.content.res.ColorStateList prev = sCslCache.putIfAbsent(key, c);
        return prev != null ? prev : c;
    }

    private static boolean isInSettingsScreen(android.view.View v) {
        try {
            // 缓存:结论由 view 所属 Activity 决定,view 生命周期内不变。
            // 该判断在 TextView.onDraw / getTextColors 热路径上被反复调用,
            // 原实现每次都要走 ContextWrapper 链 + 类名 toLowerCase + contains。
            Boolean cached;
            synchronized (sInSettingsCache) { cached = sInSettingsCache.get(v); }
            if (cached != null) return cached;
            boolean result = false;
            android.content.Context c = v.getContext();
            while (c != null) {
                if (c instanceof android.app.Activity) {
                    String n = c.getClass().getName();
                    result = SbTextUtils.containsIgnoreCase(n, "setting") || SbTextUtils.containsIgnoreCase(n, "preference");
                    break;
                }
                if (c instanceof android.content.ContextWrapper) {
                    c = ((android.content.ContextWrapper) c).getBaseContext();
                } else break;
            }
            synchronized (sInSettingsCache) { sInSettingsCache.put(v, result); }
            return result;
        } catch (Throwable ignored) {}
        return false;
    }

    private static final java.util.WeakHashMap<android.view.View, Boolean> sInSettingsCache =
            new java.util.WeakHashMap<android.view.View, Boolean>();

    /** 不分配新字符串的大小写无关包含判断(避免热路径上 toLowerCase 产生垃圾)。 */
    /** 取 view 的资源 entry name,按 view 缓存。getResourceEntryName 内部要查
     *  资源表并抛/捕获 NotFoundException(无 id 的 view 非常多),在每帧热路径上很贵。 */
    private static final java.util.WeakHashMap<android.view.View, String> sResNameCache =
            new java.util.WeakHashMap<android.view.View, String>();
    private static final String NO_RES_NAME = "";

    private static String resEntryName(android.view.View v) {
        if (v == null) return NO_RES_NAME;
        String cached;
        synchronized (sResNameCache) { cached = sResNameCache.get(v); }
        if (cached != null) return cached;
        String name = NO_RES_NAME;
        try {
            int id = v.getId();
            if (id != android.view.View.NO_ID) {
                name = v.getResources().getResourceEntryName(id);
                if (name == null) name = NO_RES_NAME;
            }
        } catch (Throwable ignored) {}
        synchronized (sResNameCache) { sResNameCache.put(v, name); }
        return name;
    }

    /** View.setTag 标记:带这个 tag 的 view 永不参与主题着色。
     *  给模块自己 new 出来的、没有资源 id 的 view 用(靠 id 名排不掉)。 */
    private static final String TAG_NO_TINT = "sbplus_no_tint";

    /** 用户明确要求「不要被主题色渲染」的图标 id。这些图标保留浏览器原色:
     *  - account: 主页右上角三星账户头像(是真实头像图,染色会变成纯色块)
     *  - news_feed_tab_add_button_icon / add_view_container / add_item_icon:
     *    主页「添加快捷方式」按钮
     *  在 isBrowserUiIcon 与 applyToolbarIconTint 两条路径上都要排除,
     *  否则一条放行另一条还是会染上。 */
    private static final java.util.HashSet<String> NEVER_TINT_IDS = new java.util.HashSet<String>(
            java.util.Arrays.asList(
                    "account",
                    "news_feed_tab_add_button",
                    "news_feed_tab_add_button_icon",
                    "add_view_container",
                    "add_item_icon"));

    /** 判断是否浏览器工具栏/菜单图标(SBrowserMainActivity 内), 位于非设置页. */

    /** 是否浏览器 UI 图标(排除设置页/主页背景/专用页; 覆盖工具栏+菜单等). */
    private static boolean isBrowserUiIcon(android.view.View v) {
        // 结论取决于 view 的 id 名、父链类型与所属 Activity。
        // 按 view 缓存结论以避免每帧走整条父链 + 多次 toLowerCase/contains。
        //
        // 2026-10-04 修复(主人反馈"底栏图标还是不能保持染色"):
        // **缓存必须随 view 的"身份"失效**。
        //
        // 原实现只按 view 实例缓存结论,注释断言"这些在 view 生命周期内都不变" ——
        // 该断言**不成立**:三星底栏/工具栏会**复用 ImageView**(RecyclerView 式),
        // 同一个实例会被重新绑定到**不同的 id / 不同的父容器**上。
        // 于是缓存里存的是"旧身份"的结论,复用后身份已变但缓存仍命中:
        // 本该染色的图标被按旧结论判为"不染" → 显示回原色;反之也可能误染。
        // 这比"view 层 tint 被重置"更深一层,是"时好时坏"的真正机制。
        //
        // 修法:把 view 的当前 id 纳入缓存校验 —— id 变化即视为身份变化,重算结论。
        // 用 id 而非 ResourceEntryName:取 id 是零成本字段读取,而 getResourceEntryName
        // 本身就要查资源表(正是本缓存想避免的开销)。
        final int vid;
        try { vid = v.getId(); } catch (Throwable t) { return computeIsBrowserUiIcon(v); }
        Integer cachedId;
        Boolean cached;
        synchronized (sBrowserIconCache) { cachedId = sBrowserIconIdCache.get(v); cached = sBrowserIconCache.get(v); }
        if (cached != null && cachedId != null && cachedId.intValue() == vid) return cached;
        boolean result = computeIsBrowserUiIcon(v);
        synchronized (sBrowserIconCache) {
            sBrowserIconCache.put(v, result);
            sBrowserIconIdCache.put(v, vid);
        }
        return result;
    }

    private static final java.util.WeakHashMap<android.view.View, Boolean> sBrowserIconCache =
            new java.util.WeakHashMap<android.view.View, Boolean>();

    /** 与 {@link #sBrowserIconCache} 配套:记录缓存结论时该 view 的 id，用于身份校验。 */
    private static final java.util.WeakHashMap<android.view.View, Integer> sBrowserIconIdCache =
            new java.util.WeakHashMap<android.view.View, Integer>();

    private static boolean computeIsBrowserUiIcon(android.view.View v) {
        try {
            // 模块自己插入的 view 显式标了「不染」
            try { if (TAG_NO_TINT.equals(v.getTag())) return false; } catch (Throwable ignoredT) {}
            // 排除背景类 id (大图背景, 绝不染)
            try {
                String vidn = resEntryName(v);
                // 用户指定永不染色的图标(账户头像 / 添加快捷方式)
                if (NEVER_TINT_IDS.contains(vidn)) return false;
                if (vidn.contains("account") || vidn.contains("avatar") || vidn.contains("profile")) return false;
                if (vidn.contains("background") || vidn.equals("custom_background")
                        || vidn.contains("backdrop") || vidn.contains("wallpaper")) return false;
                // 排除地址栏的跳转App图标(open_in_app/launch_app/external_app 等)
                if (vidn.contains("open_in") || vidn.contains("launch_app") || vidn.contains("external")
                        || vidn.contains("open_with") || vidn.contains("jump_to")) return false;
                // 地址栏底部工具图标(toolbar_ 前缀)全部排除染色,仅保留刷新与收藏
                if (vidn.startsWith("toolbar_") && !vidn.equals("toolbar_reload")
                        && !vidn.equals("toolbar_bookmarks") && !vidn.equals("toolbar_bookmark") && !vidn.equals("bookmark_star_icon")) return false;
            } catch (Throwable ignoredV) {}
            // 「添加快捷方式」的实际 ImageView id 是通用的 icon,真正能识别它的是
            // 外层容器 id(add_view_container / news_feed_tab_add_button),所以向上
            // 查几层父容器的 id;账户头像同理(ImageButton 外面还套一层 RelativeLayout)。
            try {
                android.view.ViewParent pid = v.getParent();
                int depth = 0;
                while (pid instanceof android.view.View && depth < 4) {
                    if (NEVER_TINT_IDS.contains(resEntryName((android.view.View) pid))) return false;
                    pid = pid.getParent();
                    depth++;
                }
            } catch (Throwable ignoredP) {}
            // 排除主页背景层级 + 标签页网格(网页缩略图/多标签页缩略图绝不染)
            try {
                android.view.ViewParent pp0 = v.getParent();
                while (pp0 != null) {
                    String pn0 = pp0.getClass().getName();
                    if (SbTextUtils.containsIgnoreCase(pn0, "custombackground") || SbTextUtils.containsIgnoreCase(pn0, "quickaccess")
                            || SbTextUtils.containsIgnoreCase(pn0, "videoview") || SbTextUtils.containsIgnoreCase(pn0, "textureview")
                            || SbTextUtils.containsIgnoreCase(pn0, "reelbackground") || SbTextUtils.containsIgnoreCase(pn0, "mainlayoutbackground")
                            || SbTextUtils.containsIgnoreCase(pn0, "multitab") || SbTextUtils.containsIgnoreCase(pn0, "tabgrid") || SbTextUtils.containsIgnoreCase(pn0, "tabpage")
                            || SbTextUtils.containsIgnoreCase(pn0, "tabswitcher") || SbTextUtils.containsIgnoreCase(pn0, "gallerygrid")
                            || SbTextUtils.containsIgnoreCase(pn0, "recyclerview") || SbTextUtils.containsIgnoreCase(pn0, "gridview")) return false;
                    pp0 = pp0.getParent();
                }
            } catch (Throwable ignored) {}
            android.content.Context c = v.getContext();
            while (c != null) {
                if (c instanceof android.app.Activity) {
                    String n = c.getClass().getName();
                    if (SbTextUtils.containsIgnoreCase(n, "setting") || SbTextUtils.containsIgnoreCase(n, "preference")
                            || SbTextUtils.containsIgnoreCase(n, "download") || SbTextUtils.containsIgnoreCase(n, "sniff")
                            || SbTextUtils.containsIgnoreCase(n, "userscript") || SbTextUtils.containsIgnoreCase(n, "sites")
                            || SbTextUtils.containsIgnoreCase(n, "bookmark") || SbTextUtils.containsIgnoreCase(n, "history")
                            || SbTextUtils.containsIgnoreCase(n, "adblock") || SbTextUtils.containsIgnoreCase(n, "blocker")
                            || SbTextUtils.containsIgnoreCase(n, "tracker") || SbTextUtils.containsIgnoreCase(n, "antitracking")
                            || SbTextUtils.containsIgnoreCase(n, "plugin") || SbTextUtils.containsIgnoreCase(n, "extension")) return false;
                    // 仅拦浏览器自身包
                    if (SbTextUtils.containsIgnoreCase(n, "sbrowser")) return true;
                    return false;
                }
                if (c instanceof android.content.ContextWrapper) {
                    c = ((android.content.ContextWrapper) c).getBaseContext();
                } else break;
            }
        } catch (Throwable ignored) {}
        return false;
    }

    /** 主页图标 -> S_HOME_ICON. 未设置返回 -1. */

    /** 开关三色应用. */
    private static void applySwitchColor(Object sw) {
        try {
            android.content.Context ctx = sAppContext;
            if (ctx == null || sw == null) return;
            if (!isThemeActive()) return;
            int on = ThemeColorHelper.getSlot(ctx, ThemeColorHelper.S_SWITCH_ON);
            int off = ThemeColorHelper.getSlot(ctx, ThemeColorHelper.S_SWITCH_OFF);
            int thumb = ThemeColorHelper.getSlot(ctx, ThemeColorHelper.S_SWITCH_THUMB);
            if (on == -1 && off == -1 && thumb == -1) return;
            int onCol = on == -1 ? 0xFF3E91FF : on;
            int offCol = off == -1 ? 0xFF3A3A3E : off;
            // 走缓存:每次设置页重建开关都会走到这里,原实现每次都新建两个
            // ColorStateList(含 3 个 int[] 数组)+ 两次 getMethod 反射查找。
            android.content.res.ColorStateList track = cslChecked(onCol, offCol);
            try { applyTintList(sw, "setTrackTintList", track); } catch (Throwable ignored) {}
            if (thumb != -1) {
                android.content.res.ColorStateList tl = cslFor(thumb);
                try { applyTintList(sw, "setThumbTintList", tl); } catch (Throwable ignored) {}
            }
        } catch (Throwable ignored) {}
    }

    /**
     * 反射调用 setTrackTintList / setThumbTintList,并缓存解析到的 Method。
     *
     * <p>这两个方法在部分 ROM 上不存在(故原实现用 try 包住),也可能不是 public。
     * 这里按"运行时类名 + 方法名"缓存结果;对"确实不存在"的情况也记一笔,
     * 避免每个开关都做一次注定失败的 {@code getMethod} 查找。
     *
     * <p>{@code ConcurrentHashMap} 不接受 null 值,故用一个哨兵 Method 表示"不存在"。
     */
    private static final java.util.concurrent.ConcurrentHashMap<String, java.lang.reflect.Method> sTintMethodCache
            = new java.util.concurrent.ConcurrentHashMap<String, java.lang.reflect.Method>();

    /** 哨兵:表示该 (类,方法) 已确认不存在。ConcurrentHashMap 不允许 null 值。 */
    private static final java.lang.reflect.Method ABSENT_METHOD = absentMethodSentinel();

    /** 造一个仅作标记用的 Method 实例(只用于身份比较,不会被 invoke)。 */
    private static java.lang.reflect.Method absentMethodSentinel() {
        try {
            return Object.class.getMethod("toString");
        } catch (Throwable t) {
            // 理论不可达(Object.toString 必然存在);真到了这里,退化为每次重试,
            // 只是少一层优化,不影响正确性。
            return null;
        }
    }

    private static void applyTintList(Object target, String method, android.content.res.ColorStateList list) {
        if (target == null || list == null) return;
        String key = target.getClass().getName() + "#" + method;
        java.lang.reflect.Method m = sTintMethodCache.get(key);
        if (m == null) {
            try {
                m = target.getClass().getMethod(method, android.content.res.ColorStateList.class);
                m.setAccessible(true);
            } catch (Throwable t) {
                // 记录"不存在",后续同键直接返回。哨兵为 null 时(极端)不写入,
                // 行为退化为原实现(每次重试)。
                if (ABSENT_METHOD != null) sTintMethodCache.put(key, ABSENT_METHOD);
                return;
            }
            sTintMethodCache.put(key, m);
        } else if (m == ABSENT_METHOD) {
            return;     // 已知不存在,跳过
        }
        try { m.invoke(target, list); } catch (Throwable ignored) {}
    }

    private static void injectHomeBeautify(Context ctx, ClassLoader cl, Object screen) {
        Object videoBgPref = buildVideoBgSwitch(ctx, cl);
        callMethod(screen, "addPreference", videoBgPref);

        Object clearTextPref = buildHomeClearTextSwitch(ctx, cl);
        callMethod(screen, "addPreference", clearTextPref);

        Object moveBtnPref = buildHomeMoveBtnSwitch(ctx, cl);
        callMethod(screen, "addPreference", moveBtnPref);

        Object themeEntry = ThemeColorHelper.buildEntry(ctx, cl);
        if (themeEntry != null) { callMethod(screen, "addPreference", themeEntry); }

        // -- 字体入口 --
        try {
            Object fontEntry = FontHelper.buildEntry(ctx, cl);
            if (fontEntry != null) { callMethod(screen, "addPreference", fontEntry); }
        } catch (Throwable t) {
            MainModule.logMsg("[SBPlus] font entry error: " + t);
        }


        // -- 主页 Logo 入口 --
        try {
            sHomeLogoScreen = new Object[]{ screen, ctx, cl };
            Object logoEntry = buildHomeLogoEntry(ctx, cl);
            if (logoEntry != null) { callMethod(screen, "addPreference", logoEntry); }
        } catch (Throwable t) {
            MainModule.logMsg("[SBPlus] home logo entry error: " + t);
        }

        // -- 主页时钟入口 --
        try {
            Object clockEntry = buildHomeClockEntry(ctx, cl);
            if (clockEntry != null) { callMethod(screen, "addPreference", clockEntry); }
        } catch (Throwable t) {
            MainModule.logMsg("[SBPlus] home clock entry error: " + t);
        }

        // -- 主页日期入口 --
        try {
            Object dateEntry = buildHomeDateEntry(ctx, cl);
            if (dateEntry != null) { callMethod(screen, "addPreference", dateEntry); }
        } catch (Throwable t) {
            MainModule.logMsg("[SBPlus] home date entry error: " + t);
        }

        MainModule.logMsg("[SBPlus] home beautify page injected (theme color + font)");
    }

        /** 入口:添加主页 Logo(选本地图片/GIF),显示在搜索框上方居中。 */
    /** 入口:添加主页 Logo(选本地图片/GIF),纯文字条目(无开关)+竖线图标。 */
    /** 入口:主页 Logo(带启用开关+竖线)。行点击弹列表对话框: 显示已导入图片+删除+应用状态。 */
    /** 入口:主页 Logo(Switch 条目: 右侧开关=启用/停用; 行点击=弹管理列表; 竖线图标)。 */
    private static Object buildHomeLogoEntry(Context ctx, ClassLoader cl) {
        try {
            Class<?> switchPrefCls = loadClassSafely(
                    "com.sec.android.app.sbrowser.common.settings.SwitchPreferenceCustom", cl);
            Object pref = newInstance(switchPrefCls, new Class[]{android.content.Context.class}, ctx);
            int cnt = HomeLogoHelper.listLogos(ctx).size();
            callMethod(pref, "setTitle", T("主页 Logo", "Home Logo"));
            callMethod(pref, "setKey", "sbplus_home_logo_entry");
            if (cnt == 0) {
                callMethod(pref, "setSummary", T("点击添加 Logo 图片到主页", "Tap to add a logo image"));
            } else if (HomeLogoHelper.isEnabled(ctx)) {
                callMethod(pref, "setSummary",
                        T("已添加 " + cnt + " 张，点按管理（使用中）", cnt + " logo(s), tap to manage (in use)"));
            } else {
                callMethod(pref, "setSummary",
                        T("已添加 " + cnt + " 张，点按管理（已停用）", cnt + " logo(s), tap to manage (off)"));
            }
            callMethod(pref, "setChecked", HomeLogoHelper.isEnabled(ctx));
            callMethod(pref, "setSelectable", true);
            try { callMethod(pref, "setDividerVisible", true); } catch (Throwable ignored) {}
            // 开关: 独立切换启用/停用(不弹列表)
            try {
                Class<?> chgType = listenerParamType(pref.getClass(), "setOnPreferenceChangeListener");
                Object chgL = java.lang.reflect.Proxy.newProxyInstance(cl,
                        new Class[]{chgType},
                        new java.lang.reflect.InvocationHandler() {
                            @Override
                            public Object invoke(Object proxy, java.lang.reflect.Method m, Object[] args) {
                                try {
                                    if (m.getName().equals("onPreferenceChange")) {
                                        boolean on = Boolean.TRUE.equals(args[1]);
                                        HomeLogoHelper.setEnabled(ctx, on);
                                        toastOnMain(on ? T("已启用主页 Logo", "Logo on") : T("已停用主页 Logo", "Logo off"));
                                        refreshHomeLogoSection();
                                        return Boolean.TRUE;
                                    }
                                } catch (Throwable t) {
                                    MainModule.logMsg("[SBPlus] logo switch err: " + t);
                                }
                                return Boolean.FALSE;
                            }
                        });
                callMethod(pref, "setOnPreferenceChangeListener", chgL);
            } catch (Throwable ignored) {}
            // 行点击: 拦截默认切换,弹管理列表
            try {
                Class<?> listenerType = listenerParamType(pref.getClass(), "setOnPreferenceClickListener");
                Object onPreferenceClick = java.lang.reflect.Proxy.newProxyInstance(cl,
                        new Class[]{listenerType},
                        new java.lang.reflect.InvocationHandler() {
                            @Override
                            public Object invoke(Object proxy, java.lang.reflect.Method m, Object[] args) {
                                try {
                                    if (m.getName().equals("onPreferenceClick")) {
                                        Object clicked = args[0];
                                        Object actObj = callMethod(clicked, "getContext");
                                        while (actObj instanceof android.content.ContextWrapper
                                                && !(actObj instanceof android.app.Activity)) {
                                            actObj = ((android.content.ContextWrapper) actObj).getBaseContext();
                                        }
                                        if (actObj instanceof android.app.Activity) {
                                            showHomeLogoListDialog((android.app.Activity) actObj, ctx);
                                        }
                                        return Boolean.TRUE;
                                    }
                                } catch (Throwable t) {
                                    MainModule.logMsg("[SBPlus] home logo click err: " + t);
                                }
                                return Boolean.FALSE;
                            }
                        });
                callMethod(pref, "setOnPreferenceClickListener", onPreferenceClick);
            } catch (Throwable ignored) {}
            return pref;
        } catch (Throwable t) {
            MainModule.logMsg("[SBPlus] buildHomeLogoEntry err: " + t);
            return null;
        }
    }

